  font-size: 12.5px;
  color: var(--muted);
  flex-wrap: wrap;
  gap: 12px;
}
.foot-bottom .pay { display: flex; gap: 8px; }
.foot-bottom .pay span {
  border: 1px solid var(--line);
  padding: 4px 10px;
  border-radius: 6px;
  font-weight: 600;
  letter-spacing: .04em;
  background: #fff;
}

/* ---------- Responsive ---------- */
@media (max-width: 1080px) {
  .products { grid-template-columns: repeat(3, 1fr); }
  .cat-grid { grid-template-columns: repeat(3, 1fr); }
  .deal-grid { grid-template-columns: 1fr 1fr; }
