arguments.file_text:
:root {
  --bg: #fafaf7;
  --surface: #ffffff;
  --ink: #0e0e0c;
  --ink-soft: #4a4a44;
  --muted: #8c8c84;
  --line: #ececea;
  --accent: #ff5a1f;
  --accent-ink: #ffffff;
  --sand: #f1ede4;
  --olive: #3a4a2a;
  --plum: #2a1f2e;
  --radius: 14px;
  --radius-lg: 22px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,.04);
  --shadow-md: 0 8px 30px rgba(15,15,12,.08);
  --container: 1240px;
  --font: "Inter", "Helvetica Neue", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
  --serif: "Fraunces", "Playfair Display", "Times New Roman", Georgia, serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
img { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; color: inherit; }

.container {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 28px;
}

/* ---------- Top announcement ---------- */
.announce {
  background: var(--ink);
  color: #fff;
  font-size: 12.5px;
  letter-spacing: .08em;
  text-transform: uppercase;
}
.announce-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 36px;
}
.announce-inner span { opacity: .8; }
.announce-rotator {
  flex: 1;
  text-align: center;
  font-weight: 500;
}
.announce a { opacity: .85; }
.announce a:hover { opacity: 1; }

/* ---------- Header ---------- */
.header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(250,250,247,.85);
  backdrop-filter: saturate(140%) blur(12px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  height: 72px;
  gap: 24px;
}
.brand {
  font-family: var(--serif);
  font-weight: 600;
  font-size: 22px;
  letter-spacing: -.02em;
}
.brand .dot { color: var(--accent); }
.nav {
  display: flex;
  gap: 28px;
  justify-content: center;
}
.nav a {
  font-size: 14px;
  font-weight: 500;
  color: var(--ink-soft);
  position: relative;
  padding: 6px 0;
}
.nav a::after {
  content: "";
  position: absolute;
  left: 0; right: 0; bottom: 0;
  height: 1.5px;
  background: var(--ink);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform .25s ease;
}
.nav a:hover { color: var(--ink); }
.nav a:hover::after { transform: scaleX(1); }

.icons {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 8px;
}
.icon-btn {
  width: 40px; height: 40px;
  display: inline-flex; align-items: center; justify-content: center;
  border-radius: 999px;
  color: var(--ink);
  transition: background .2s ease;
  position: relative;
}
.icon-btn:hover { background: var(--sand); }
.icon-btn .badge {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--accent);
  color: #fff;
  font-size: 10px;
  font-weight: 600;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
  line-height: 1;
}

/* ---------- Hero ---------- */
.hero {
  padding: 28px 0 0;
}
.hero-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: linear-gradient(120deg, #efe9dd 0%, #f6efe2 60%, #ece4d3 100%);
  min-height: 560px;
  display: grid;
  grid-template-columns: 1.05fr .95fr;
  align-items: stretch;
}
.hero-copy {
  padding: 64px 56px;
  display: flex; flex-direction: column; justify-content: center;
  position: relative;
  z-index: 2;
}
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--ink-soft);
  font-weight: 600;
  margin-bottom: 18px;
}
.eyebrow::before {
  content: "";
  width: 22px; height: 1px; background: var(--ink-soft);
}
.hero h1 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(40px, 5.6vw, 76px);
  line-height: 1.02;
  letter-spacing: -.02em;
  margin: 0 0 22px;
  color: var(--ink);
}
.hero h1 em {
  font-style: italic;
  color: var(--olive);
}
.hero p.lede {
  font-size: 17px;
  color: var(--ink-soft);
  max-width: 460px;
  margin: 0 0 32px;
}
.cta-row {
  display: flex; gap: 12px; flex-wrap: wrap;
  margin-bottom: 36px;
}
.btn {
  display: inline-flex; align-items: center; gap: 10px;
  padding: 14px 22px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 14px;
  transition: transform .15s ease, background .2s ease, color .2s ease;
}
.btn-primary {
  background: var(--ink);
  color: #fff;
}
.btn-primary:hover { background: #2a2a26; transform: translateY(-1px); }
.btn-ghost {
  background: transparent;
  color: var(--ink);
  border: 1px solid var(--ink);
}
.btn-ghost:hover { background: var(--ink); color: #fff; }
.btn svg { width: 16px; height: 16px; }

.hero-meta {
  display: flex; gap: 36px;
  border-top: 1px solid rgba(14,14,12,.12);
  padding-top: 22px;
  max-width: 480px;
}
.hero-meta div { font-size: 13px; color: var(--ink-soft); }
.hero-meta strong {
  display: block;
  font-family: var(--serif);
  font-weight: 600;
  font-size: 22px;
  color: var(--ink);
  margin-bottom: 2px;
  letter-spacing: -.01em;
}

.hero-visual {
  position: relative;
  overflow: hidden;
}
.hero-visual img {
  width: 100%; height: 100%;
  object-fit: cover;
}
.hero-tag {
  position: absolute;
  bottom: 28px; left: 28px;
  background: rgba(255,255,255,.92);
  backdrop-filter: blur(6px);
  padding: 14px 16px;
  border-radius: 14px;
  display: flex; align-items: center; gap: 12px;
  box-shadow: var(--shadow-md);
  max-width: 280px;
}
.hero-tag .swatch {
  width: 44px; height: 44px;
  border-radius: 10px;
  background: linear-gradient(135deg, #c08c5a, #6b4a2b);
  flex-shrink: 0;
}
.hero-tag .t-name { font-weight: 600; font-size: 14px; }
.hero-tag .t-price { font-size: 13px; color: var(--ink-soft); }

/* Marquee */
.marquee {
  margin-top: 36px;
  padding: 22px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  overflow: hidden;
  position: relative;
}
.marquee-track {
  display: flex;
  gap: 56px;
  animation: scroll 38s linear infinite;
  white-space: nowrap;
  width: max-content;
}
.marquee span {
  font-family: var(--serif);
  font-style: italic;
  font-size: 22px;
  color: var(--ink-soft);
  display: inline-flex; align-items: center; gap: 56px;
}
.marquee span::after {
  content: "✦";
  color: var(--accent);
  font-style: normal;
  font-size: 14px;
}
@keyframes scroll {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}

/* ---------- Section base ---------- */
section { padding: 88px 0; }
.section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 36px;
  flex-wrap: wrap;
}
.section-head h2 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(30px, 3.6vw, 46px);
  line-height: 1.05;
  letter-spacing: -.02em;
  margin: 8px 0 0;
}
.section-head p {
  color: var(--ink-soft);
  max-width: 420px;
  margin: 8px 0 0;
}
.head-link {
  font-size: 14px;
  font-weight: 600;
  display: inline-flex; align-items: center; gap: 6px;
  border-bottom: 1.5px solid var(--ink);
  padding-bottom: 2px;
}

/* ---------- Categories ---------- */
.categories {
  padding-top: 64px;
}
.cat-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
}
.cat {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  aspect-ratio: 4/5;
  background: var(--sand);
  cursor: pointer;
}
.cat img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .6s ease;
}
.cat:hover img { transform: scale(1.06); }
.cat::after {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(0,0,0,.5));
}
.cat-label {
  position: absolute;
  left: 18px; bottom: 16px;
  color: #fff;
  z-index: 2;
}
.cat-label .name { font-weight: 600; font-size: 17px; }
.cat-label .count { font-size: 12.5px; opacity: .85; }

/* ---------- Filters / Featured ---------- */
.tabs {
  display: flex; gap: 6px;
  background: var(--sand);
  padding: 5px;
  border-radius: 999px;
  margin-bottom: 32px;
  width: fit-content;
}
.tab {
  padding: 9px 18px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 600;
  color: var(--ink-soft);
  transition: all .2s ease;
}
.tab.active {
  background: var(--ink);
  color: #fff;
}
.tab:not(.active):hover { color: var(--ink); }

.products {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.product {
  position: relative;
}
.product-media {
  position: relative;
  background: var(--sand);
  border-radius: var(--radius);
  overflow: hidden;
  aspect-ratio: 4/5;
  margin-bottom: 14px;
}
.product-media img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .5s ease;
}
.product:hover .product-media img { transform: scale(1.04); }
.badge-tag {
  position: absolute; top: 12px; left: 12px;
  background: #fff;
  color: var(--ink);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: 6px 10px;
  border-radius: 999px;
}
.badge-tag.sale { background: var(--accent); color: #fff; }
.badge-tag.new { background: var(--ink); color: #fff; }
.wish {
  position: absolute; top: 12px; right: 12px;
  width: 36px; height: 36px;
  background: rgba(255,255,255,.95);
  border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
  opacity: 0;
  transform: translateY(-4px);
  transition: all .25s ease;
}
.product:hover .wish { opacity: 1; transform: translateY(0); }
.wish.active svg { fill: var(--accent); stroke: var(--accent); }
.wish svg { width: 16px; height: 16px; stroke: var(--ink); fill: none; stroke-width: 2; }

.quick-add {
  position: absolute;
  left: 12px; right: 12px; bottom: 12px;
  background: var(--ink);
  color: #fff;
  text-align: center;
  padding: 12px;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 600;
  opacity: 0;
  transform: translateY(8px);
  transition: all .25s ease;
}
.product:hover .quick-add { opacity: 1; transform: translateY(0); }
.quick-add:hover { background: var(--accent); }

.product-info { display: flex; flex-direction: column; gap: 4px; }
.product-info .cat-name {
  font-size: 11.5px;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 600;
}
.product-info .name {
  font-size: 15px;
  font-weight: 600;
  color: var(--ink);
}
.product-info .price-row {
  display: flex; align-items: center; gap: 10px;
  margin-top: 4px;
}
.price { font-weight: 600; font-size: 15px; }
.price-was { color: var(--muted); text-decoration: line-through; font-size: 13px; }
.swatches { display: flex; gap: 6px; margin-top: 8px; }
.sw {
  width: 14px; height: 14px;
  border-radius: 999px;
  border: 1px solid rgba(0,0,0,.1);
}

/* ---------- Deals ---------- */
.deals {
  background: var(--ink);
  color: #fff;
  border-radius: var(--radius-lg);
  margin: 0 28px;
  max-width: calc(var(--container) - 0px);
  padding: 72px 56px;
}
.deals-wrap { max-width: var(--container); margin: 0 auto; }
.deals .section-head h2 { color: #fff; }
.deals .section-head p { color: rgba(255,255,255,.7); }
.deals .head-link { color: #fff; border-bottom-color: #fff; }
.deals-container { padding: 0; }
.timer {
  display: flex; gap: 12px; margin-top: 16px;
}
.timer-cell {
  background: rgba(255,255,255,.08);
  padding: 10px 14px;
  border-radius: 10px;
  text-align: center;
  min-width: 64px;
}
.timer-cell strong {
  display: block;
  font-family: var(--serif);
  font-size: 26px;
  font-weight: 500;
  letter-spacing: -.02em;
}
.timer-cell span {
  font-size: 10.5px;
  letter-spacing: .14em;
  text-transform: uppercase;
  opacity: .7;
}

.deal-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 18px;
  margin-top: 36px;
}
.deal {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  background: #1a1a18;
  min-height: 220px;
  display: flex; flex-direction: column; justify-content: flex-end;
  padding: 22px;
  cursor: pointer;
}
.deal::before {
  content: "";
  position: absolute; inset: 0;
  background-size: cover;
  background-position: center;
  opacity: .55;
  transition: opacity .3s ease, transform .6s ease;
}
.deal:hover::before { opacity: .7; transform: scale(1.04); }
.deal::after {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(0deg, rgba(0,0,0,.7), rgba(0,0,0,0) 60%);
}
.deal > * { position: relative; z-index: 1; }
.deal.large { grid-row: span 2; min-height: 460px; }

.deal .pct {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 500;
  font-size: 36px;
  line-height: 1;
  color: var(--accent);
  margin-bottom: 8px;
}
.deal.large .pct { font-size: 64px; }
.deal h3 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: 22px;
  margin: 0 0 4px;
  letter-spacing: -.01em;
}
.deal.large h3 { font-size: 34px; }
.deal p { color: rgba(255,255,255,.75); font-size: 13px; margin: 0; }

/* Deal background images via inline style in JS */

/* ---------- Editorial ---------- */
.editorial {
  background: var(--sand);
  margin-top: 56px;
}
.editorial .container { max-width: var(--container); }
.edit-grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 28px;
}
.edit-feature {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  min-height: 540px;
  background: #d6cdb8;
}
.edit-feature img {
  position: absolute; inset: 0;
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .8s ease;
}
.edit-feature:hover img { transform: scale(1.04); }
.edit-feature .copy {
  position: relative;
  z-index: 1;
  padding: 44px;
  margin-top: auto;
  height: 100%;
  display: flex; flex-direction: column; justify-content: flex-end;
  background: linear-gradient(0deg, rgba(0,0,0,.65) 0%, rgba(0,0,0,0) 55%);
  color: #fff;
}
.edit-feature .tag {
  font-size: 11px; letter-spacing: .14em; text-transform: uppercase;
  font-weight: 600; opacity: .85;
}
.edit-feature h3 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(28px, 3vw, 40px);
  letter-spacing: -.01em;
  line-height: 1.1;
  margin: 12px 0 8px;
  max-width: 460px;
}
.edit-feature .meta { font-size: 13px; opacity: .85; }

.edit-list { display: flex; flex-direction: column; gap: 18px; }
.edit-item {
  background: #fff;
  border-radius: var(--radius);
  padding: 14px;
  display: grid;
  grid-template-columns: 140px 1fr;
  gap: 18px;
  cursor: pointer;
  transition: transform .25s ease, box-shadow .25s ease;
}
.edit-item:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.edit-item .thumb {
  border-radius: 10px;
  overflow: hidden;
  aspect-ratio: 1;
  background: var(--sand);
}
.edit-item .thumb img { width: 100%; height: 100%; object-fit: cover; }
.edit-item .body { display: flex; flex-direction: column; justify-content: center; }
.edit-item .tag { font-size: 11px; letter-spacing: .12em; text-transform: uppercase; color: var(--accent); font-weight: 700; }
.edit-item h4 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: 19px;
  margin: 6px 0 4px;
  letter-spacing: -.01em;
  line-height: 1.2;
}
.edit-item .meta { font-size: 12.5px; color: var(--muted); }

/* ---------- Value props ---------- */
.values {
  padding: 48px 0;
}
.values-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
}
.value {
  display: flex; gap: 14px; align-items: flex-start;
  padding: 22px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}
.value-icon {
  width: 42px; height: 42px;
  border-radius: 10px;
  background: var(--sand);
  display: inline-flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.value-icon svg { width: 20px; height: 20px; stroke: var(--ink); fill: none; stroke-width: 1.6; }
.value h4 { margin: 0 0 4px; font-size: 14px; font-weight: 600; }
.value p { margin: 0; font-size: 12.5px; color: var(--muted); line-height: 1.5; }

/* ---------- Newsletter ---------- */
.news {
  padding: 96px 0;
}
.news-card {
  background: var(--olive);
  color: #fff;
  border-radius: var(--radius-lg);
  padding: 64px;
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 48px;
  align-items: center;
  position: relative;
  overflow: hidden;
}
.news-card::before {
  content: "✦";
  position: absolute;
  top: -40px; right: 60px;
  font-size: 240px;
  color: rgba(255,255,255,.06);
  font-family: var(--serif);
}
.news-card h2 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(28px, 3.4vw, 44px);
  line-height: 1.1;
  letter-spacing: -.02em;
  margin: 8px 0 12px;
}
.news-card p { color: rgba(255,255,255,.78); margin: 0 0 0; max-width: 420px; }
.news-form {
  display: flex; gap: 8px;
  background: rgba(255,255,255,.08);
  padding: 6px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,.18);
}
.news-form input {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  color: #fff;
  font-family: inherit;
  font-size: 14px;
  padding: 12px 18px;
}
.news-form input::placeholder { color: rgba(255,255,255,.55); }
.news-form button {
