  border-radius: 999px;
  font-weight: 600;
  font-size: 13px;
}
.news-form button:hover { background: var(--accent); color: #fff; }
.news small { display: block; margin-top: 12px; font-size: 12px; opacity: .65; }

/* ---------- Footer ---------- */
.footer {
  border-top: 1px solid var(--line);
  padding: 64px 0 32px;
  background: var(--bg);
}
.foot-grid {
  display: grid;
  grid-template-columns: 1.6fr repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}
.foot-brand .brand { font-size: 26px; }
.foot-brand p {
  color: var(--ink-soft);
  font-size: 13.5px;
  max-width: 280px;
  margin: 14px 0 22px;
}
.socials { display: flex; gap: 8px; }
.socials a {
  width: 36px; height: 36px;
  border-radius: 999px;
  border: 1px solid var(--line);
  display: inline-flex; align-items: center; justify-content: center;
}
.socials a:hover { background: var(--ink); color: #fff; border-color: var(--ink); }
.socials svg { width: 15px; height: 15px; }

.foot-col h5 {
  font-size: 12px;
  letter-spacing: .12em;
  text-transform: uppercase;
  margin: 0 0 16px;
  font-weight: 700;
}
.foot-col ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 10px; }
.foot-col a { color: var(--ink-soft); font-size: 13.5px; }
.foot-col a:hover { color: var(--ink); }

.foot-bottom {
  border-top: 1px solid var(--line);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  font-size: 12.5px;
  color: var(--muted);
  flex-wrap: wrap;
  gap: 12px;
}
.foot-bottom .pay { display: flex; gap: 8px; }
.foot-bottom .pay span {
  border: 1px solid var(--line);
  padding: 4px 10px;
  border-radius: 6px;
  font-weight: 600;
  letter-spacing: .04em;
  background: #fff;
}

/* ---------- Responsive ---------- */
@media (max-width: 1080px) {
  .products { grid-template-columns: repeat(3, 1fr); }
  .cat-grid { grid-template-columns: repeat(3, 1fr); }
  .deal-grid { grid-template-columns: 1fr 1fr; }
  .deal.large { grid-row: span 1; min-height: 280px; }
  .foot-grid { grid-template-columns: 1.2fr repeat(2, 1fr); }
}
@media (max-width: 820px) {
  .nav { display: none; }
  .header-inner { grid-template-columns: 1fr 1fr; }
  .hero-card { grid-template-columns: 1fr; min-height: auto; }
  .hero-copy { padding: 44px 28px; }
  .hero-visual { min-height: 360px; }
  .products { grid-template-columns: repeat(2, 1fr); }
  .values-grid { grid-template-columns: repeat(2, 1fr); }
  .edit-grid { grid-template-columns: 1fr; }
  .news-card { grid-template-columns: 1fr; padding: 40px 28px; }
  .deals { padding: 48px 28px; margin: 0 16px; }
  section { padding: 56px 0; }
}
@media (max-width: 540px) {
  .container { padding: 0 18px; }
  .cat-grid { grid-template-columns: repeat(2, 1fr); }
  .deal-grid { grid-template-columns: 1fr; }
  .values-grid { grid-template-columns: 1fr; }
  .edit-item { grid-template-columns: 100px 1fr; }
  .foot-grid { grid-template-columns: 1fr 1fr; }
  .announce-inner span:first-child, .announce-inner a { display: none; }
}

