  transform: scaleX(0);
  transform-origin: left;
  transition: transform .25s ease;
}
.nav a:hover { color: var(--ink); }
.nav a:hover::after { transform: scaleX(1); }

.icons {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 8px;
}
.icon-btn {
  width: 40px; height: 40px;
