/* Marquee */
.marquee {
  margin-top: 36px;
  padding: 22px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  overflow: hidden;
  position: relative;
}
.marquee-track {
  display: flex;
