const Countdown = () => {
  const [t, setT] = useState({ d: 2, h: 14, m: 32, s: 18 });
  useEffect(() => {
    const id = setInterval(() => {
      setT(prev => {
        let { d, h: hh, m, s } = prev;
        s--;
        if (s < 0) { s = 59; m--; }
        if (m < 0) { m = 59; hh--; }
        if (hh < 0) { hh = 23; d--; }
        if (d < 0) { d = 0; }
        return { d, h: hh, m, s };
      });
    }, 1000);
    return () => clearInterval(id);
  }, []);
  const cell = (n, l) => h("div", { className: "timer-cell" }, h("strong", null, String(n).padStart(2, "0")), h("span", null, l));
  return h("div", { className: "timer" }, cell(t.d, "Days"), cell(t.h, "Hrs"), cell(t.m, "Min"), cell(t.s, "Sec"));
};

